mapper.select:
select from t_role
and (`role` like concat('%',#{keyword},'%') or role_name like concat('%',#{keyword},'%')) and enabled = #{enabled}
order by authorization_level desc, id

select from t_role role_record
protected_role = 0 and scope_type = 'ORGANIZATION' and authorization_level < #{authorizationLevel} and exists (select 1 from t_role_organization visible_link where visible_link.role_id = role_record.id) and not exists (select 1 from t_role_organization outside_link where outside_link.role_id = role_record.id and outside_link.organization_unit_id not in #{organizationUnitId}) and (`role` like concat('%',#{keyword},'%') or role_name like concat('%',#{keyword},'%')) and enabled = #{enabled}
order by authorization_level desc, id
